// Prepare three user records. Each object is like one database row.
const users = [
  { name: "Mia", city: "Shanghai" },
  { name: "Lin", city: "Beijing" },
  { name: "Zhou", city: "Guangzhou" }
];

// Ask a question: find the record whose name is Lin.
// find returns the first record that matches the condition.
const wantedUser = users.find((user) => user.name === "Lin");

console.log("User found:", wantedUser);
console.log("Saved data can be retrieved by a condition.");

// Each object represents one row in the students table.
const students = [
  { name: "Mia", city: "Shanghai", age: 18 },
  { name: "Lin", city: "Beijing", age: 19 },
  { name: "Zhou", city: "Beijing", age: 18 }
];

// filter keeps every row that matches the condition.
const studentsInBeijing = students.filter((student) => student.city === "Beijing");

console.log("Students in Beijing:", studentsInBeijing);

