// This array simulates a students table.
let students = [
  { name: "Mia", city: "Shanghai" },
  { name: "Lin", city: "Beijing" }
];

// SELECT: view students in Beijing.
console.log("Query result:", students.filter((student) => student.city === "Beijing"));

// INSERT: add one new record.
students.push({ name: "Zhou", city: "Guangzhou" });

// UPDATE: find Lin and change only his city.
const studentToUpdate = students.find((student) => student.name === "Lin");
if (studentToUpdate) {
  studentToUpdate.city = "Hangzhou";
}

// DELETE: keep everyone except Zhou, which removes Zhou.
students = students.filter((student) => student.name !== "Zhou");

console.log("Final students table:", students);
